def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Track opponent defection streak from the end
    opp_def_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            opp_def_streak += 1
        else:
            break

    my_def_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][0] == 'D':
            my_def_streak += 1
        else:
            break

    # Opponent cooperation rate overall and recent
    opp_c = 0
    for h in history:
        if h[1] == 'C':
            opp_c += 1

    w = 12
    start = n - w if n > w else 0
    recent_c = 0
    recent_total = n - start
    for i in range(start, n):
        if history[i][1] == 'C':
            recent_c += 1
    recent_rate = recent_c / recent_total if recent_total else 0.5
    overall_rate = opp_c / n

    last_my, last_op = history[-1]
    rounds_left = 100 - n

    # Opening: cooperate to enable mutual cooperation
    if n < 4:
        if last_op == 'D':
            return 'D'
        return 'C'

    # Strong defector: punish, but still occasionally forgive to allow recovery
    if overall_rate < 0.25 and recent_rate < 0.3:
        if opp_def_streak >= 4 and rng.random() < 0.1:
            return 'C'
        return 'D'

    # Endgame: exploit sufficiently cooperative opponents; otherwise defend
    if rounds_left <= 2:
        if overall_rate >= 0.5:
            return 'D'
        if last_op == 'D':
            return 'D'
        return 'C'

    if rounds_left <= 5:
        if recent_rate >= 0.7:
            return 'C'
        if recent_rate <= 0.3:
            return 'D'
        if last_op == 'D':
            return 'D'
        return 'C'

    # Mutual cooperation: preserve it, with rare careful probing
    if last_op == 'C' and recent_rate >= 0.7:
        if opp_def_streak == 0 and my_def_streak == 0 and n >= 15:
            if rng.random() < 0.03 and rounds_left > 10:
                return 'D'
        return 'C'

    # Opponent just defected
    if last_op == 'D':
        # Just punished last round: go back to cooperation to end retaliation
        if last_my == 'D':
            if recent_rate >= 0.4:
                return 'C'
            if opp_def_streak >= 3:
                if rng.random() < 0.25:
                    return 'C'
                return 'D'
            return 'C'

        # Single isolated defection: punish once
        if opp_def_streak == 1 and overall_rate >= 0.5:
            return 'D'

        # Long defection streak: retaliate
        if opp_def_streak >= 3:
            if recent_rate >= 0.5 and rng.random() < 0.2:
                return 'C'
            return 'D'

        # Alternating retaliation pattern: try conciliatory move
        if n >= 2 and history[-2][1] == 'C':
            if rng.random() < 0.35:
                return 'C'
        return 'D'

    # Opponent just cooperated but we defected: return to cooperation
    if last_my == 'D':
        return 'C'

    # Mostly cooperative opponent, keep cooperating
    if recent_rate >= 0.5:
        return 'C'

    # Ambiguous opponent: mostly cooperate, occasional defense
    if recent_rate < 0.35:
        if rng.random() < 0.4:
            return 'D'
    return 'C'
